1	/**
2	 * @module useActiveSession
3	 *
4	 * Hook para gerenciamento de sessões ativas de expedição.
5	 *
6	 * Uma "sessão ativa" é um rascunho temporário de requisição que pode ser
7	 * editado colaborativamente antes de ser persistido como requisição formal.
8	 * Integra com `active_sessions` e `active_session_items` no Supabase.
9	 *
10	 * @example
11	 * ```ts
12	 * const { activeSession, items, loadSession, addItem, removeItem } = useActiveSession();
13	 * ```
14	 */
15	
16	import { useState, useEffect, useCallback } from 'react';
17	import { supabase } from '@/integrations/supabase/client';
18	import { toast } from 'sonner';
19	import { parseDateFromTitle, coerceISODateString } from '@/shared/lib/utils';
20	import { normalizeStoreName, getStoreLabel } from '@/shared/ui/StoreSelector';
21	import { logSeparationEvent, logSeparationCompleted } from '@/shared/lib/expedition-log-service';
22	import { recordRequisition, recordOperation, recordDuration, recordError } from '@/shared/lib/telemetry/metrics';
23	import { wideInfo, wideError } from '@/shared/lib/telemetry/wide-events';
24	
25	export interface ActiveSessionData {
26	  session_id: string;
27	  requester_name: string;
28	  preparer_name: string;
29	  store_requester: string;
30	  store_preparer: string;
31	  order_date: string;
32	  received_date: string;
33	  status: 'editing' | 'separating' | 'completed';
34	  created_by: string;
35	  created_at: string;
36	  updated_at: string;
37	  expires_at: string;
38	}
39	
40	export interface ActiveSessionItem {
41	  id: string;
42	  session_id: string;
43	  item_name: string;
44	  requested_quantity: number;
45	  sent_quantity: string;
46	  observation: string;
47	  is_separated: boolean;
48	  separated_by: string;
49	  category?: string;
50	  categoria_manual?: string;
51	  unidade_medida?: string | null;
52	  // Link ao produto_master — essencial para matching no bip de separação.
53	  // Sem isso, slots.findIndex(s => s.produtoMasterId === scannedPid) sempre falha
54	  // e todos os bips viram "extra".
55	  produto_master_id?: number | null;
56	  order_index: number;
57	  updated_at: string;
58	}
59	
60	export interface AIProcessedItem {
61	  name: string;
62	  requested: number;
63	  sent: string;
64	  observation?: string;
65	  id: string;
66	  is_separated?: boolean;
67	  separated_by?: string;
68	  separated_at?: string;
69	  category?: string;
70	  manualCategory?: string;
71	  unidade_medida?: string | null;
72	  matchedId?: string;
73	}
74	
75	export function useActiveSession() {
76	  const [currentSession, setCurrentSession] = useState<ActiveSessionData | null>(null);
77	  const [sessionItems, setSessionItems] = useState<ActiveSessionItem[]>([]);
78	  const [isLoading, setIsLoading] = useState(false);
79	
80	  // Criar nova sessão ativa
81	  const createSession = useCallback(async (
82	    requesterName: string,
83	    preparerName: string,
84	    storeRequester: string,
85	    storePreparer: string,
86	    orderDate: string,
87	    receivedDate: string,
88	    items: AIProcessedItem[]
89	  ): Promise<ActiveSessionData | null> => {
90	    setIsLoading(true);
91	    try {
92	      // Obter usuário atual
93	      const { data: { user } } = await supabase.auth.getUser();
94	      if (!user) {
95	        toast.error('Usuário não autenticado');
96	        return null;
97	      }
98	
99	      // Criar sessão principal
100	      const { data: session, error: sessionError } = await supabase
101	        .from('active_sessions')
102	        .insert({
103	          requester_name: requesterName,
104	          preparer_name: preparerName,
105	          store_requester: storeRequester,
106	          store_preparer: storePreparer,
107	          order_date: orderDate,
108	          received_date: receivedDate,
109	          status: 'editing',
110	          created_by: user.id
111	        })
112	        .select()
113	        .single();
114	
115	      if (sessionError) {
116	        toast.error('Erro ao criar sessão ativa');
117	        recordError('REQUISICAO_CREATE_SESSION_FAILED', 'SupabaseError', { 'error.message': sessionError.message });
118	        wideError('requisicao.criar', 'Erro ao criar sessão ativa', { domain: 'requisicao', attributes: { 'error.message': sessionError.message, 'operation.name': 'createSession' } });
119	        return null;
120	      }
121	
122	      // Criar itens da sessão
123	      if (items.length > 0) {
124	        const itemsToInsert = items.map((item, index) => ({
125	          session_id: session.session_id,
126	          item_name: item.name,
127	          requested_quantity: item.requested,
128	          sent_quantity: item.sent || '',
129	          observation: item.observation || '',
130	          is_separated: item.is_separated || false,
131	          separated_by: item.separated_by || '',
132	          category: item.category ?? null,
133	          categoria_manual: item.manualCategory ?? null,
134	          unidade_medida: item.unidade_medida || 'cx',
135	          // Source of truth pro matching no bip — herda do matchedId da AI
136	          // (que é a referência ao produtos_master.id encontrada no catálogo).
137	          produto_master_id: item.matchedId ? Number(item.matchedId) : null,
138	          order_index: index
139	        }));
140	
141	        const { error: itemsError } = await supabase
142	          .from('active_session_items')
143	          .insert(itemsToInsert);
144	
145	        if (itemsError) {
146	          toast.error('Erro ao criar itens da sessão');
147	          recordError('REQUISICAO_CREATE_ITEMS_FAILED', 'SupabaseError', { 'error.message': itemsError.message });
148	          wideError('requisicao.criar', 'Erro ao criar itens da sessão', { domain: 'requisicao', attributes: { 'session.id': session.session_id, 'error.message': itemsError.message, 'operation.name': 'createSession' } });
149	          return null;
150	        }
151	      }
152	
153	      // Telemetria — requisição criada com sucesso
154	      recordRequisition(items.length, { 'session.id': session.session_id, 'store.requester': storeRequester, 'store.preparer': storePreparer });
155	      wideInfo('requisicao.criar', 'Requisição criada com sucesso', { domain: 'requisicao', attributes: { 'session.id': session.session_id, 'requisicao.item_count': items.length, 'store.requester': storeRequester, 'store.preparer': storePreparer, 'store.name': storeRequester } });
156	
157	      setCurrentSession(session);
158	      toast.success('Sessão ativa criada com sucesso!');
159	      return session as ActiveSessionData;
160	    } catch (error) {
161	      toast.error('Erro ao criar sessão ativa');
162	      recordError('REQUISICAO_CREATE_FAILED', 'UnexpectedError', { 'error.message': error instanceof Error ? error.message : String(error) });
163	      wideError('requisicao.criar', 'Erro inesperado ao criar sessão', { domain: 'requisicao', attributes: { 'error.message': error instanceof Error ? error.message : String(error), 'operation.name': 'createSession' } });
164	      return null;
165	    } finally {
166	      setIsLoading(false);
167	    }
168	  }, []);
169	
170	  // Carregar sessão existente
171	  const loadSession = useCallback(async (sessionId: string) => {
172	    setIsLoading(true);
173	    try {
174	      // Carregar dados da sessão
175	      const { data: session, error: sessionError } = await supabase
176	        .from('active_sessions')
177	        .select('*')
178	        .eq('session_id', sessionId)
179	        .single();
180	
181	      if (sessionError) {
182	        wideError('requisicao.carregar', 'Erro ao carregar sessão', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': sessionError.message, 'operation.name': 'loadSession' } });
183	        toast.error('Sessão não encontrada');
184	        return false;
185	      }
186	
187	      // Carregar itens da sessão
188	      const { data: items, error: itemsError } = await supabase
189	        .from('active_session_items')
190	        .select('*')
191	        .eq('session_id', sessionId)
192	        .order('order_index');
193	
194	      if (itemsError) {
195	        wideError('requisicao.carregar', 'Erro ao carregar itens da sessão', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': itemsError.message, 'operation.name': 'loadSession' } });
196	        toast.error('Erro ao carregar itens da sessão');
197	        return false;
198	      }
199	
200	      setCurrentSession(session);
201	      setSessionItems(items || []);
202	      return true;
203	    } catch (error) {
204	      wideError('requisicao.carregar', 'Erro inesperado ao carregar sessão', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': error instanceof Error ? error.message : String(error), 'operation.name': 'loadSession' } });
205	      toast.error('Erro ao carregar sessão');
206	      return false;
207	    } finally {
208	      setIsLoading(false);
209	    }
210	  }, []);
211	
212	  // Atualizar dados da sessão
213	  const updateSession = useCallback(async (
214	    sessionId: string,
215	    updates: Partial<ActiveSessionData>
216	  ) => {
217	    try {
218	      const { error } = await supabase
219	        .from('active_sessions')
220	        .update(updates)
221	        .eq('session_id', sessionId);
222	
223	      if (error) {
224	        wideError('requisicao.atualizar', 'Erro ao atualizar sessão', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': error.message, 'operation.name': 'updateSession' } });
225	        return false;
226	      }
227	
228	      // Atualizar estado local
229	      setCurrentSession(prev => prev ? { ...prev, ...updates } : null);
230	      return true;
231	    } catch (error) {
232	      wideError('requisicao.atualizar', 'Erro inesperado ao atualizar sessão', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': error instanceof Error ? error.message : String(error), 'operation.name': 'updateSession' } });
233	      return false;
234	    }
235	  }, []);
236	
237	  // Atualizar item da sessão
238	  const updateSessionItem = useCallback(async (
239	    itemId: string,
240	    updates: Partial<ActiveSessionItem>,
241	    // Parâmetros opcionais para logging de expedição
242	    loggingContext?: {
243	      requisicaoId?: number;
244	      userName?: string;
245	      storeName?: string;
246	    }
247	  ) => {
248	    try {
249	      const { error } = await supabase
250	        .from('active_session_items')
251	        .update(updates)
252	        .eq('id', itemId);
253	
254	      if (error) {
255	        wideError('requisicao.atualizarItem', 'Erro ao atualizar item', { domain: 'requisicao', attributes: { 'item.id': itemId, 'error.message': error.message, 'operation.name': 'updateSessionItem' } });
256	        return false;
257	      }
258	
259	      // Atualizar estado local
260	      setSessionItems(prev =>
261	        prev.map(item =>
262	          item.id === itemId ? { ...item, ...updates } : item
263	        )
264	      );
265	
266	      // Se o item foi marcado como separado, registrar log de expedição
267	      if (updates.is_separated === true && loggingContext?.requisicaoId && loggingContext?.userName) {
268	        const itemName = sessionItems.find(i => i.id === itemId)?.item_name || 'Item';
269	        const sentQty = updates.sent_quantity || sessionItems.find(i => i.id === itemId)?.sent_quantity || '0';
270	
271	        await logSeparationEvent(
272	          loggingContext.requisicaoId,
273	          itemName,
274	          loggingContext.userName,
275	          sentQty,
276	          loggingContext.storeName || 'Loja'
277	        );
278	      }
279	
280	      return true;
281	    } catch (error) {
282	      wideError('requisicao.atualizarItem', 'Erro inesperado ao atualizar item', { domain: 'requisicao', attributes: { 'item.id': itemId, 'error.message': error instanceof Error ? error.message : String(error), 'operation.name': 'updateSessionItem' } });
283	      return false;
284	    }
285	  }, [sessionItems]);
286	
287	  // Adicionar item à sessão
288	  const addSessionItem = useCallback(async (
289	    sessionId: string,
290	    item: Omit<ActiveSessionItem, 'id' | 'session_id' | 'updated_at'>
291	  ): Promise<ActiveSessionItem | null> => {
292	    try {
293	      const { data, error } = await supabase
294	        .from('active_session_items')
295	        .insert({
296	          session_id: sessionId,
297	          ...item
298	        })
299	        .select()
300	        .single();
301	
302	      if (error) {
303	        wideError('requisicao.adicionarItem', 'Erro ao adicionar item', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': error.message, 'operation.name': 'addSessionItem' } });
304	        return null;
305	      }
306	
307	      setSessionItems(prev => [...prev, data]);
308	      return data as ActiveSessionItem;
309	    } catch (error) {
310	      wideError('requisicao.adicionarItem', 'Erro inesperado ao adicionar item', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': error instanceof Error ? error.message : String(error), 'operation.name': 'addSessionItem' } });
311	      return null;
312	    }
313	  }, []);
314	
315	  // Remover item da sessão
316	  const removeSessionItem = useCallback(async (itemId: string) => {
317	    try {
318	      const { error } = await supabase
319	        .from('active_session_items')
320	        .delete()
321	        .eq('id', itemId);
322	
323	      if (error) {
324	        wideError('requisicao.removerItem', 'Erro ao remover item', { domain: 'requisicao', attributes: { 'item.id': itemId, 'error.message': error.message, 'operation.name': 'removeSessionItem' } });
325	        return false;
326	      }
327	
328	      setSessionItems(prev => prev.filter(item => item.id !== itemId));
329	      return true;
330	    } catch (error) {
331	      wideError('requisicao.removerItem', 'Erro inesperado ao remover item', { domain: 'requisicao', attributes: { 'item.id': itemId, 'error.message': error instanceof Error ? error.message : String(error), 'operation.name': 'removeSessionItem' } });
332	      return false;
333	    }
334	  }, []);
335	
336	  // Finalizar sessão (mover para histórico)
337	  const finalizeSession = useCallback(async (
338	    sessionId: string,
339	    listName: string,
340	    sendToQueue?: boolean
341	  ) => {
342	    if (!currentSession) return false;
343	
344	    const startTime = performance.now();
345	    try {
346	      const { data: { user } } = await supabase.auth.getUser();
347	      const currentUserId = user?.id || null;
348	      // Normalizar lojas e corrigir data conforme definido pelo usuário na sessão
349	      const normalizedRequesterValue = normalizeStoreName(currentSession.store_requester) || currentSession.store_requester;
350	      const lojaSolicitante = getStoreLabel(normalizedRequesterValue);
351	      // Sempre definir local de envio como Fábrica
352	      const lojaPreparadora = 'Fábrica';
353	      const orderDateToSave = coerceISODateString(currentSession.order_date);
354	      const receivedDateToSave = coerceISODateString(currentSession.received_date);
355	
356	      // Preparar dados base da requisição
357	      const headData: Record<string, any> = {
358	        nome: listName,
359	        solicitante: currentSession.requester_name,
360	        preparador: currentSession.preparer_name,
361	        loja_solicitante: lojaSolicitante,
362	        loja_preparadora: lojaPreparadora,
363	        data_pedido: orderDateToSave,
364	        data_recebimento: receivedDateToSave,
365	      };
366	
367	      let requisicao: any = null;
368	
369	      if (sendToQueue) {
370	        // Fluxo: enviar para fila → sempre criar uma nova requisição em_fila
371	        const { data, error } = await supabase
372	          .from('requisicoes')
373	          .insert({ ...headData, status: 'em_fila', user_id: currentUserId })
374	          .select()
375	          .single();
376	        if (error) {
377	          toast.error('Erro ao salvar requisição na fila');
378	          recordError('REQUISICAO_SAVE_QUEUE_FAILED', 'SupabaseError', { 'error.message': error.message });
379	          wideError('requisicao.finalizar', 'Erro ao salvar requisição na fila', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': error.message, 'operation.name': 'finalizeSession' } });
380	          return false;
381	        }
382	        requisicao = data;
383	      } else {
384	        // Fluxo: finalizar → tentar reutilizar a requisição em_fila existente
385	        const { data: existingReq, error: findErr } = await supabase
386	          .from('requisicoes')
387	          .select('id')
388	          .eq('solicitante', headData.solicitante)
389	          .eq('preparador', headData.preparador)
390	          .eq('loja_solicitante', headData.loja_solicitante)
391	          .eq('loja_preparadora', headData.loja_preparadora)
392	          .eq('data_pedido', headData.data_pedido)
393	          .eq('status', 'em_fila')
394	          .maybeSingle();
395	
396	        if (findErr) {
397	          wideError('requisicao.finalizar', 'Falha ao buscar requisição em_fila existente', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': findErr.message, 'operation.name': 'finalizeSession' } });
398	        }
399	
400	        if (existingReq?.id) {
401	          // Atualizar a requisição existente para manter status e padronizar cabeçalho
402	          const { error: updErr } = await supabase
403	            .from('requisicoes')
404	            .update({
405	              ...headData,
406	              status: 'em_fila',
407	              user_id: currentUserId
408	            })
409	            .eq('id', existingReq.id);
410	
411	          if (updErr) {
412	            toast.error('Erro ao atualizar requisição existente');
413	            recordError('REQUISICAO_UPDATE_EXISTING_FAILED', 'SupabaseError', { 'error.message': updErr.message });
414	            wideError('requisicao.finalizar', 'Erro ao atualizar requisição existente', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': updErr.message, 'operation.name': 'finalizeSession' } });
415	            return false;
416	          }
417	
418	          requisicao = { id: existingReq.id };
419	
420	          // Substituir itens existentes pelos da sessão para evitar duplicidade/divergência
421	          const { error: delErr } = await supabase
422	            .from('requisicoes_itens')
423	            .delete()
424	            .eq('requisicao_id', existingReq.id);
425	          if (delErr) {
426	            toast.error('Erro ao substituir itens da requisição');
427	            recordError('REQUISICAO_DELETE_ITEMS_FAILED', 'SupabaseError', { 'error.message': delErr.message });
428	            wideError('requisicao.finalizar', 'Erro ao limpar itens antigos', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': delErr.message, 'operation.name': 'finalizeSession' } });
429	            return false;
430	          }
431	        } else {
432	          // Nenhuma em_fila compatível: inserir com status 'em_fila'
433	          const { data, error } = await supabase
434	            .from('requisicoes')
435	            .insert({ ...headData, status: 'em_fila', user_id: currentUserId })
436	            .select()
437	            .single();
438	          if (error) {
439	            toast.error('Erro ao salvar requisição');
440	            recordError('REQUISICAO_SAVE_FINALIZE_FAILED', 'SupabaseError', { 'error.message': error.message });
441	            wideError('requisicao.finalizar', 'Erro ao salvar requisição (finalização)', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': error.message, 'operation.name': 'finalizeSession' } });
442	            return false;
443	          }
444	          requisicao = data;
445	        }
446	      }
447	
448	      // Mover itens para o histórico — propaga produto_master_id (vira produto_id
449	       // em requisicoes_itens) e unidade_medida para conferencia/separacao posteriores
450	       // saberem o produto/unidade real sem precisar fazer fuzzy match por nome.
451	      const itensToInsert = sessionItems.map((item, index) => ({
452	        requisicao_id: requisicao.id,
453	        nome_produto: item.item_name,
454	        quantidade_solicitada: Number(item.requested_quantity ?? 0),
455	        quantidade_enviada: item.sent_quantity ?? '',
456	        observacao: item.observation || '',
457	        ordem: Number.isFinite(index) ? index : 0,
458	        category: item.category ?? null,
459	        categoria_manual: item.categoria_manual ?? null,
460	        produto_id: item.produto_master_id ?? null,
461	        unidade_medida: item.unidade_medida || 'cx',
462	      }));
463	
464	      const { error: itensError } = await supabase
465	        .from('requisicoes_itens')
466	        .insert(itensToInsert);
467	
468	      if (itensError) {
469	        toast.error('Erro ao salvar itens da requisição');
470	        recordError('REQUISICAO_SAVE_ITEMS_FAILED', 'SupabaseError', { 'error.message': itensError.message });
471	        wideError('requisicao.finalizar', 'Erro ao salvar itens da requisição', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': itensError.message, 'operation.name': 'finalizeSession' } });
472	        return false;
473	      }
474	
475	      // Marcar sessão como completada
476	      await updateSession(sessionId, { status: 'completed' });
477	
478	      // Registrar log de conclusão da separação (se a requisição estiver vinculada a uma expedição)
479	      // A função logSeparationCompleted verifica internamente se há expedição vinculada
480	      const preparerName = currentSession.preparer_name || 'Sistema';
481	      const storeName = getStoreLabel(normalizeStoreName(currentSession.store_requester) || currentSession.store_requester);
482	      await logSeparationCompleted(requisicao.id, preparerName, storeName, sessionItems.length);
483	
484	      // Telemetria — requisição finalizada com sucesso
485	      const durationMs = performance.now() - startTime;
486	      recordOperation('requisicao.finalizar', { 'session.id': sessionId, 'store.name': storeName });
487	      recordDuration('requisicao.finalizar', durationMs, { 'session.id': sessionId });
488	      wideInfo('requisicao.finalizar', 'Requisição finalizada com sucesso', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'requisicao.id': requisicao.id, 'requisicao.item_count': sessionItems.length, 'store.name': storeName, 'requisicao.duration_ms': Math.round(durationMs), 'requisicao.send_to_queue': !!sendToQueue } });
489	
490	      // Limpar dados locais
491	      setCurrentSession(null);
492	      setSessionItems([]);
493	
494	      toast.success(`Requisição "${listName}" salva no histórico`);
495	      return true;
496	    } catch (error) {
497	      toast.error('Erro ao finalizar sessão');
498	      const durationMs = performance.now() - startTime;
499	      recordError('REQUISICAO_FINALIZE_FAILED', 'UnexpectedError', { 'error.message': error instanceof Error ? error.message : String(error) });
500	      recordDuration('requisicao.finalizar', durationMs, { 'session.id': sessionId, 'error': 'true' });
501	      wideError('requisicao.finalizar', 'Erro ao finalizar sessão', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': error instanceof Error ? error.message : String(error), 'requisicao.duration_ms': Math.round(durationMs), 'operation.name': 'finalizeSession' } });
502	      return false;
503	    }
504	  }, [currentSession, sessionItems, updateSession]);
505	
506	  // Atualizar item da sessão pelo nome do item
507	  const updateSessionItemByName = useCallback(async (
508	    sessionId: string,
509	    itemName: string,
510	    updates: Partial<ActiveSessionItem>
511	  ) => {
512	    try {
513	      const { error } = await supabase
514	        .from('active_session_items')
515	        .update(updates)
516	        .eq('session_id', sessionId)
517	        .eq('item_name', itemName);
518	
519	      if (error) {
520	        wideError('requisicao.atualizarItemPorNome', 'Erro ao atualizar item por nome', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'item.name': itemName, 'error.message': error.message, 'operation.name': 'updateSessionItemByName' } });
521	        return false;
522	      }
523	
524	      // Atualizar estado local
525	      setSessionItems(prev =>
526	        prev.map(item =>
527	          item.session_id === sessionId && item.item_name === itemName
528	            ? { ...item, ...updates }
529	            : item
530	        )
531	      );
532	      return true;
533	    } catch (error) {
534	      wideError('requisicao.atualizarItemPorNome', 'Erro inesperado ao atualizar item por nome', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'item.name': itemName, 'error.message': error instanceof Error ? error.message : String(error), 'operation.name': 'updateSessionItemByName' } });
535	      return false;
536	    }
537	  }, []);
538	
539	  // Converter itens da sessão para formato AIProcessedItem
540	  const getItemsAsAIProcessed = useCallback((): AIProcessedItem[] => {
541	    return sessionItems.map(item => ({
542	      id: item.id,
543	      name: item.item_name,
544	      requested: item.requested_quantity,
545	      sent: item.sent_quantity,
546	      observation: item.observation,
547	      is_separated: item.is_separated,
548	      separated_by: item.separated_by,
549	      separated_at: item.updated_at,
550	      category: item.category,
551	      manualCategory: item.categoria_manual
552	    }));
553	  }, [sessionItems]);
554	
555	  return {
556	    currentSession,
557	    sessionItems,
558	    isLoading,
559	    createSession,
560	    loadSession,
561	    updateSession,
562	    updateSessionItem,
563	    updateSessionItemByName,
564	    addSessionItem,
565	    removeSessionItem,
566	    finalizeSession,
567	    getItemsAsAIProcessed
568	  };
569	}
