/**
 * @module useActiveSession
 *
 * Hook para gerenciamento de sessões ativas de expedição.
 *
 * Uma "sessão ativa" é um rascunho temporário de requisição que pode ser
 * editado colaborativamente antes de ser persistido como requisição formal.
 * Integra com `active_sessions` e `active_session_items` no Supabase.
 *
 * @example
 * ```ts
 * const { activeSession, items, loadSession, addItem, removeItem } = useActiveSession();
 * ```
 */

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';
import { parseDateFromTitle, coerceISODateString } from '@/shared/lib/utils';
import { normalizeStoreName, getStoreLabel } from '@/shared/ui/StoreSelector';
import { logSeparationEvent, logSeparationCompleted } from '@/shared/lib/expedition-log-service';
import { recordRequisition, recordOperation, recordDuration, recordError } from '@/shared/lib/telemetry/metrics';
import { wideInfo, wideError } from '@/shared/lib/telemetry/wide-events';

export interface ActiveSessionData {
  session_id: string;
  requester_name: string;
  preparer_name: string;
  store_requester: string;
  store_preparer: string;
  order_date: string;
  received_date: string;
  status: 'editing' | 'separating' | 'completed';
  created_by: string;
  created_at: string;
  updated_at: string;
  expires_at: string;
}

export interface ActiveSessionItem {
  id: string;
  session_id: string;
  item_name: string;
  requested_quantity: number;
  sent_quantity: string;
  observation: string;
  is_separated: boolean;
  separated_by: string;
  category?: string;
  categoria_manual?: string;
  unidade_medida?: string | null;
  // Link ao produto_master — essencial para matching no bip de separação.
  // Sem isso, slots.findIndex(s => s.produtoMasterId === scannedPid) sempre falha
  // e todos os bips viram "extra".
  produto_master_id?: number | null;
  order_index: number;
  updated_at: string;
}

export interface AIProcessedItem {
  name: string;
  requested: number;
  sent: string;
  observation?: string;
  id: string;
  is_separated?: boolean;
  separated_by?: string;
  separated_at?: string;
  category?: string;
  manualCategory?: string;
  unidade_medida?: string | null;
  matchedId?: string;
}

export function useActiveSession() {
  const [currentSession, setCurrentSession] = useState<ActiveSessionData | null>(null);
  const [sessionItems, setSessionItems] = useState<ActiveSessionItem[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  // Criar nova sessão ativa
  const createSession = useCallback(async (
    requesterName: string,
    preparerName: string,
    storeRequester: string,
    storePreparer: string,
    orderDate: string,
    receivedDate: string,
    items: AIProcessedItem[]
  ): Promise<ActiveSessionData | null> => {
    setIsLoading(true);
    try {
      // Obter usuário atual
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        toast.error('Usuário não autenticado');
        return null;
      }

      // Criar sessão principal
      const { data: session, error: sessionError } = await supabase
        .from('active_sessions')
        .insert({
          requester_name: requesterName,
          preparer_name: preparerName,
          store_requester: storeRequester,
          store_preparer: storePreparer,
          order_date: orderDate,
          received_date: receivedDate,
          status: 'editing',
          created_by: user.id
        })
        .select()
        .single();

      if (sessionError) {
        toast.error('Erro ao criar sessão ativa');
        recordError('REQUISICAO_CREATE_SESSION_FAILED', 'SupabaseError', { 'error.message': sessionError.message });
        wideError('requisicao.criar', 'Erro ao criar sessão ativa', { domain: 'requisicao', attributes: { 'error.message': sessionError.message, 'operation.name': 'createSession' } });
        return null;
      }

      // Criar itens da sessão
      if (items.length > 0) {
        const itemsToInsert = items.map((item, index) => ({
          session_id: session.session_id,
          item_name: item.name,
          requested_quantity: item.requested,
          sent_quantity: item.sent || '',
          observation: item.observation || '',
          is_separated: item.is_separated || false,
          separated_by: item.separated_by || '',
          category: item.category ?? null,
          categoria_manual: item.manualCategory ?? null,
          unidade_medida: item.unidade_medida || 'cx',
          // Source of truth pro matching no bip — herda do matchedId da AI
          // (que é a referência ao produtos_master.id encontrada no catálogo).
          produto_master_id: item.matchedId ? Number(item.matchedId) : null,
          order_index: index
        }));

        const { error: itemsError } = await supabase
          .from('active_session_items')
          .insert(itemsToInsert);

        if (itemsError) {
          toast.error('Erro ao criar itens da sessão');
          recordError('REQUISICAO_CREATE_ITEMS_FAILED', 'SupabaseError', { 'error.message': itemsError.message });
          wideError('requisicao.criar', 'Erro ao criar itens da sessão', { domain: 'requisicao', attributes: { 'session.id': session.session_id, 'error.message': itemsError.message, 'operation.name': 'createSession' } });
          return null;
        }
      }

      // Telemetria — requisição criada com sucesso
      recordRequisition(items.length, { 'session.id': session.session_id, 'store.requester': storeRequester, 'store.preparer': storePreparer });
      wideInfo('requisicao.criar', 'Requisição criada com sucesso', { domain: 'requisicao', attributes: { 'session.id': session.session_id, 'requisicao.item_count': items.length, 'store.requester': storeRequester, 'store.preparer': storePreparer, 'store.name': storeRequester } });

      setCurrentSession(session);
      toast.success('Sessão ativa criada com sucesso!');
      return session as ActiveSessionData;
    } catch (error) {
      toast.error('Erro ao criar sessão ativa');
      recordError('REQUISICAO_CREATE_FAILED', 'UnexpectedError', { 'error.message': error instanceof Error ? error.message : String(error) });
      wideError('requisicao.criar', 'Erro inesperado ao criar sessão', { domain: 'requisicao', attributes: { 'error.message': error instanceof Error ? error.message : String(error), 'operation.name': 'createSession' } });
      return null;
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Carregar sessão existente
  const loadSession = useCallback(async (sessionId: string) => {
    setIsLoading(true);
    try {
      // Carregar dados da sessão
      const { data: session, error: sessionError } = await supabase
        .from('active_sessions')
        .select('*')
        .eq('session_id', sessionId)
        .single();

      if (sessionError) {
        wideError('requisicao.carregar', 'Erro ao carregar sessão', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': sessionError.message, 'operation.name': 'loadSession' } });
        toast.error('Sessão não encontrada');
        return false;
      }

      // Carregar itens da sessão
      const { data: items, error: itemsError } = await supabase
        .from('active_session_items')
        .select('*')
        .eq('session_id', sessionId)
        .order('order_index');

      if (itemsError) {
        wideError('requisicao.carregar', 'Erro ao carregar itens da sessão', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': itemsError.message, 'operation.name': 'loadSession' } });
        toast.error('Erro ao carregar itens da sessão');
        return false;
      }

      setCurrentSession(session);
      setSessionItems(items || []);
      return true;
    } catch (error) {
      wideError('requisicao.carregar', 'Erro inesperado ao carregar sessão', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': error instanceof Error ? error.message : String(error), 'operation.name': 'loadSession' } });
      toast.error('Erro ao carregar sessão');
      return false;
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Atualizar dados da sessão
  const updateSession = useCallback(async (
    sessionId: string,
    updates: Partial<ActiveSessionData>
  ) => {
    try {
      const { error } = await supabase
        .from('active_sessions')
        .update(updates)
        .eq('session_id', sessionId);

      if (error) {
        wideError('requisicao.atualizar', 'Erro ao atualizar sessão', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': error.message, 'operation.name': 'updateSession' } });
        return false;
      }

      // Atualizar estado local
      setCurrentSession(prev => prev ? { ...prev, ...updates } : null);
      return true;
    } catch (error) {
      wideError('requisicao.atualizar', 'Erro inesperado ao atualizar sessão', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': error instanceof Error ? error.message : String(error), 'operation.name': 'updateSession' } });
      return false;
    }
  }, []);

  // Atualizar item da sessão
  const updateSessionItem = useCallback(async (
    itemId: string,
    updates: Partial<ActiveSessionItem>,
    // Parâmetros opcionais para logging de expedição
    loggingContext?: {
      requisicaoId?: number;
      userName?: string;
      storeName?: string;
    }
  ) => {
    try {
      const { error } = await supabase
        .from('active_session_items')
        .update(updates)
        .eq('id', itemId);

      if (error) {
        wideError('requisicao.atualizarItem', 'Erro ao atualizar item', { domain: 'requisicao', attributes: { 'item.id': itemId, 'error.message': error.message, 'operation.name': 'updateSessionItem' } });
        return false;
      }

      // Atualizar estado local
      setSessionItems(prev =>
        prev.map(item =>
          item.id === itemId ? { ...item, ...updates } : item
        )
      );

      // Se o item foi marcado como separado, registrar log de expedição
      if (updates.is_separated === true && loggingContext?.requisicaoId && loggingContext?.userName) {
        const itemName = sessionItems.find(i => i.id === itemId)?.item_name || 'Item';
        const sentQty = updates.sent_quantity || sessionItems.find(i => i.id === itemId)?.sent_quantity || '0';

        await logSeparationEvent(
          loggingContext.requisicaoId,
          itemName,
          loggingContext.userName,
          sentQty,
          loggingContext.storeName || 'Loja'
        );
      }

      return true;
    } catch (error) {
      wideError('requisicao.atualizarItem', 'Erro inesperado ao atualizar item', { domain: 'requisicao', attributes: { 'item.id': itemId, 'error.message': error instanceof Error ? error.message : String(error), 'operation.name': 'updateSessionItem' } });
      return false;
    }
  }, [sessionItems]);

  // Adicionar item à sessão
  const addSessionItem = useCallback(async (
    sessionId: string,
    item: Omit<ActiveSessionItem, 'id' | 'session_id' | 'updated_at'>
  ): Promise<ActiveSessionItem | null> => {
    try {
      const { data, error } = await supabase
        .from('active_session_items')
        .insert({
          session_id: sessionId,
          ...item
        })
        .select()
        .single();

      if (error) {
        wideError('requisicao.adicionarItem', 'Erro ao adicionar item', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': error.message, 'operation.name': 'addSessionItem' } });
        return null;
      }

      setSessionItems(prev => [...prev, data]);
      return data as ActiveSessionItem;
    } catch (error) {
      wideError('requisicao.adicionarItem', 'Erro inesperado ao adicionar item', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': error instanceof Error ? error.message : String(error), 'operation.name': 'addSessionItem' } });
      return null;
    }
  }, []);

  // Remover item da sessão
  const removeSessionItem = useCallback(async (itemId: string) => {
    try {
      const { error } = await supabase
        .from('active_session_items')
        .delete()
        .eq('id', itemId);

      if (error) {
        wideError('requisicao.removerItem', 'Erro ao remover item', { domain: 'requisicao', attributes: { 'item.id': itemId, 'error.message': error.message, 'operation.name': 'removeSessionItem' } });
        return false;
      }

      setSessionItems(prev => prev.filter(item => item.id !== itemId));
      return true;
    } catch (error) {
      wideError('requisicao.removerItem', 'Erro inesperado ao remover item', { domain: 'requisicao', attributes: { 'item.id': itemId, 'error.message': error instanceof Error ? error.message : String(error), 'operation.name': 'removeSessionItem' } });
      return false;
    }
  }, []);

  // Finalizar sessão (mover para histórico)
  const finalizeSession = useCallback(async (
    sessionId: string,
    listName: string,
    sendToQueue?: boolean
  ) => {
    if (!currentSession) return false;

    const startTime = performance.now();
    try {
      const { data: { user } } = await supabase.auth.getUser();
      const currentUserId = user?.id || null;
      // Normalizar lojas e corrigir data conforme definido pelo usuário na sessão
      const normalizedRequesterValue = normalizeStoreName(currentSession.store_requester) || currentSession.store_requester;
      const lojaSolicitante = getStoreLabel(normalizedRequesterValue);
      // Sempre definir local de envio como Fábrica
      const lojaPreparadora = 'Fábrica';
      const orderDateToSave = coerceISODateString(currentSession.order_date);
      const receivedDateToSave = coerceISODateString(currentSession.received_date);

      // Preparar dados base da requisição
      const headData: Record<string, any> = {
        nome: listName,
        solicitante: currentSession.requester_name,
        preparador: currentSession.preparer_name,
        loja_solicitante: lojaSolicitante,
        loja_preparadora: lojaPreparadora,
        data_pedido: orderDateToSave,
        data_recebimento: receivedDateToSave,
      };

      let requisicao: any = null;

      if (sendToQueue) {
        // Fluxo: enviar para fila → sempre criar uma nova requisição em_fila
        const { data, error } = await supabase
          .from('requisicoes')
          .insert({ ...headData, status: 'em_fila', user_id: currentUserId })
          .select()
          .single();
        if (error) {
          toast.error('Erro ao salvar requisição na fila');
          recordError('REQUISICAO_SAVE_QUEUE_FAILED', 'SupabaseError', { 'error.message': error.message });
          wideError('requisicao.finalizar', 'Erro ao salvar requisição na fila', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': error.message, 'operation.name': 'finalizeSession' } });
          return false;
        }
        requisicao = data;
      } else {
        // Fluxo: finalizar → tentar reutilizar a requisição em_fila existente
        const { data: existingReq, error: findErr } = await supabase
          .from('requisicoes')
          .select('id')
          .eq('solicitante', headData.solicitante)
          .eq('preparador', headData.preparador)
          .eq('loja_solicitante', headData.loja_solicitante)
          .eq('loja_preparadora', headData.loja_preparadora)
          .eq('data_pedido', headData.data_pedido)
          .eq('status', 'em_fila')
          .maybeSingle();

        if (findErr) {
          wideError('requisicao.finalizar', 'Falha ao buscar requisição em_fila existente', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': findErr.message, 'operation.name': 'finalizeSession' } });
        }

        if (existingReq?.id) {
          // Atualizar a requisição existente para manter status e padronizar cabeçalho
          const { error: updErr } = await supabase
            .from('requisicoes')
            .update({
              ...headData,
              status: 'em_fila',
              user_id: currentUserId
            })
            .eq('id', existingReq.id);

          if (updErr) {
            toast.error('Erro ao atualizar requisição existente');
            recordError('REQUISICAO_UPDATE_EXISTING_FAILED', 'SupabaseError', { 'error.message': updErr.message });
            wideError('requisicao.finalizar', 'Erro ao atualizar requisição existente', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': updErr.message, 'operation.name': 'finalizeSession' } });
            return false;
          }

          requisicao = { id: existingReq.id };

          // Substituir itens existentes pelos da sessão para evitar duplicidade/divergência
          const { error: delErr } = await supabase
            .from('requisicoes_itens')
            .delete()
            .eq('requisicao_id', existingReq.id);
          if (delErr) {
            toast.error('Erro ao substituir itens da requisição');
            recordError('REQUISICAO_DELETE_ITEMS_FAILED', 'SupabaseError', { 'error.message': delErr.message });
            wideError('requisicao.finalizar', 'Erro ao limpar itens antigos', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': delErr.message, 'operation.name': 'finalizeSession' } });
            return false;
          }
        } else {
          // Nenhuma em_fila compatível: inserir com status 'em_fila'
          const { data, error } = await supabase
            .from('requisicoes')
            .insert({ ...headData, status: 'em_fila', user_id: currentUserId })
            .select()
            .single();
          if (error) {
            toast.error('Erro ao salvar requisição');
            recordError('REQUISICAO_SAVE_FINALIZE_FAILED', 'SupabaseError', { 'error.message': error.message });
            wideError('requisicao.finalizar', 'Erro ao salvar requisição (finalização)', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': error.message, 'operation.name': 'finalizeSession' } });
            return false;
          }
          requisicao = data;
        }
      }

      // Mover itens para o histórico — propaga produto_master_id (vira produto_id
       // em requisicoes_itens) e unidade_medida para conferencia/separacao posteriores
       // saberem o produto/unidade real sem precisar fazer fuzzy match por nome.
      const itensToInsert = sessionItems.map((item, index) => ({
        requisicao_id: requisicao.id,
        nome_produto: item.item_name,
        quantidade_solicitada: Number(item.requested_quantity ?? 0),
        quantidade_enviada: item.sent_quantity ?? '',
        observacao: item.observation || '',
        ordem: Number.isFinite(index) ? index : 0,
        category: item.category ?? null,
        categoria_manual: item.categoria_manual ?? null,
        produto_id: item.produto_master_id ?? null,
        unidade_medida: item.unidade_medida || 'cx',
      }));

      const { error: itensError } = await supabase
        .from('requisicoes_itens')
        .insert(itensToInsert);

      if (itensError) {
        toast.error('Erro ao salvar itens da requisição');
        recordError('REQUISICAO_SAVE_ITEMS_FAILED', 'SupabaseError', { 'error.message': itensError.message });
        wideError('requisicao.finalizar', 'Erro ao salvar itens da requisição', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': itensError.message, 'operation.name': 'finalizeSession' } });
        return false;
      }

      // Marcar sessão como completada
      await updateSession(sessionId, { status: 'completed' });

      // Registrar log de conclusão da separação (se a requisição estiver vinculada a uma expedição)
      // A função logSeparationCompleted verifica internamente se há expedição vinculada
      const preparerName = currentSession.preparer_name || 'Sistema';
      const storeName = getStoreLabel(normalizeStoreName(currentSession.store_requester) || currentSession.store_requester);
      await logSeparationCompleted(requisicao.id, preparerName, storeName, sessionItems.length);

      // Telemetria — requisição finalizada com sucesso
      const durationMs = performance.now() - startTime;
      recordOperation('requisicao.finalizar', { 'session.id': sessionId, 'store.name': storeName });
      recordDuration('requisicao.finalizar', durationMs, { 'session.id': sessionId });
      wideInfo('requisicao.finalizar', 'Requisição finalizada com sucesso', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'requisicao.id': requisicao.id, 'requisicao.item_count': sessionItems.length, 'store.name': storeName, 'requisicao.duration_ms': Math.round(durationMs), 'requisicao.send_to_queue': !!sendToQueue } });

      // Limpar dados locais
      setCurrentSession(null);
      setSessionItems([]);

      toast.success(`Requisição "${listName}" salva no histórico`);
      return true;
    } catch (error) {
      toast.error('Erro ao finalizar sessão');
      const durationMs = performance.now() - startTime;
      recordError('REQUISICAO_FINALIZE_FAILED', 'UnexpectedError', { 'error.message': error instanceof Error ? error.message : String(error) });
      recordDuration('requisicao.finalizar', durationMs, { 'session.id': sessionId, 'error': 'true' });
      wideError('requisicao.finalizar', 'Erro ao finalizar sessão', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'error.message': error instanceof Error ? error.message : String(error), 'requisicao.duration_ms': Math.round(durationMs), 'operation.name': 'finalizeSession' } });
      return false;
    }
  }, [currentSession, sessionItems, updateSession]);

  // Atualizar item da sessão pelo nome do item
  const updateSessionItemByName = useCallback(async (
    sessionId: string,
    itemName: string,
    updates: Partial<ActiveSessionItem>
  ) => {
    try {
      const { error } = await supabase
        .from('active_session_items')
        .update(updates)
        .eq('session_id', sessionId)
        .eq('item_name', itemName);

      if (error) {
        wideError('requisicao.atualizarItemPorNome', 'Erro ao atualizar item por nome', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'item.name': itemName, 'error.message': error.message, 'operation.name': 'updateSessionItemByName' } });
        return false;
      }

      // Atualizar estado local
      setSessionItems(prev =>
        prev.map(item =>
          item.session_id === sessionId && item.item_name === itemName
            ? { ...item, ...updates }
            : item
        )
      );
      return true;
    } catch (error) {
      wideError('requisicao.atualizarItemPorNome', 'Erro inesperado ao atualizar item por nome', { domain: 'requisicao', attributes: { 'session.id': sessionId, 'item.name': itemName, 'error.message': error instanceof Error ? error.message : String(error), 'operation.name': 'updateSessionItemByName' } });
      return false;
    }
  }, []);

  // Converter itens da sessão para formato AIProcessedItem
  const getItemsAsAIProcessed = useCallback((): AIProcessedItem[] => {
    return sessionItems.map(item => ({
      id: item.id,
      name: item.item_name,
      requested: item.requested_quantity,
      sent: item.sent_quantity,
      observation: item.observation,
      is_separated: item.is_separated,
      separated_by: item.separated_by,
      separated_at: item.updated_at,
      category: item.category,
      manualCategory: item.categoria_manual
    }));
  }, [sessionItems]);

  return {
    currentSession,
    sessionItems,
    isLoading,
    createSession,
    loadSession,
    updateSession,
    updateSessionItem,
    updateSessionItemByName,
    addSessionItem,
    removeSessionItem,
    finalizeSession,
    getItemsAsAIProcessed
  };
}

