597	
598	      {/* AlertDialog — transferir separacao de outra requisicao */}
599	      <AlertDialog open={reseparirDialog.open} onOpenChange={(o) => !o && setReseparirDialog({ open: false, uid: "", produto: "", separada_at: null, payload: null })}>
600	        <AlertDialogContent className="max-w-md rounded-3xl">
601	          <AlertDialogHeader>
