603	              <AlertTriangle className="w-5 h-5" />
604	              Etiqueta já separada
605	            </AlertDialogTitle>
606	            <AlertDialogDescription asChild>
607	              <div className="space-y-3 text-sm">
608	                <p>
609	                  <b className="text-foreground">{reseparirDialog.produto}</b> já foi separada{" "}
610	                  {reseparirDialog.separada_at && (
611	                    <span className="text-foreground">
612	                      em <b>{new Date(reseparirDialog.separada_at).toLocaleString("pt-BR", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" })}</b>
613	                    </span>
614	                  )} (em outra requisição).
615	                </p>
616	                <p className="text-orange-700 font-semibold">
617	                  Deseja transferir a separação para esta requisição?
618	                </p>
619	                <p className="text-xs text-muted-foreground">
620	                  A etiqueta passa a contar para esta requisição. O histórico fica registrado na timeline.
621	                </p>
622	              </div>
623	            </AlertDialogDescription>
624	          </AlertDialogHeader>
625	          <AlertDialogFooter>
626	            <AlertDialogCancel className="rounded-xl">Cancelar</AlertDialogCancel>
627	            <AlertDialogAction onClick={confirmarReseparar} className="bg-orange-600 hover:bg-orange-700 rounded-xl">
